style.css:
body {
  background-color: black;
  font-family: Arial;
  color: white;
}
p {
  color: #00ff00;
}
h1, h2, h3, h4, h5, h6 {
  color: #ff00ff;
}
img, video {
  filter: grayscale(1);
}
a {
  color: #ff00ff;
}
button, input, form, textarea {
  color: #00ff00;
  border: 1px solid #00ff00;
  background-color: #000000;
}
table, tr, td, th {
  color: #00ff00;
  border: 1px solid #00ff00;
  background-color: #000000;
}
path {
  color: #00ff00;
}
